record.field:
if (taxes := record.taxes_id.filtered('x_is_excise')):
    record['taxes_id'] = [Command.unlink(id) for id in taxes.ids]
if (taxes := record.supplier_taxes_id.filtered('x_is_excise')):
    record['supplier_taxes_id'] = [Command.unlink(id) for id in taxes.ids]
if (categ := record.x_excise_category):
    record.write({'taxes_id': [Command.link(categ.x_sales_tax_id.id)], 'supplier_taxes_id': [Command.link(categ.x_purchase_tax_id.id)]})

no_excises_taxes = env.ref('excise_management.no_excise_tax_sale') | env.ref('excise_management.no_excise_tax_purchase')
for fp in records:
    if fp.x_is_fiscal_deposit:
        no_excises_taxes['fiscal_position_ids'] = [Command.link(fp.id)]
    else:
        no_excises_taxes['fiscal_position_ids'] = [Command.unlink(fp.id)]

all_taxes = env['account.tax'].sudo().search([], order="x_is_excise desc, sequence asc")
for idx, tax in enumerate(all_taxes, start=1):
    tax['sequence'] = idx

excise_licenses = env['x_excise_license'].search([]).ids + [False]
last_excise_report = env['x_excise_report']._read_group(domain=[('x_excise_license_id', 'in', excise_licenses)], groupby=['x_excise_license_id'], aggregates=['x_to_date:max'])
last_excise_report_date_dict = {(license_rec.id if license_rec else False): last_date    for license_rec, last_date in last_excise_report}
for license in excise_licenses:
    from_date, to_date = last_excise_report_date_dict.get(license, datetime.date.today() - datetime.timedelta(days=7)), datetime.date.today()
    if from_date < to_date:
        res_id = env['x_excise_report'].create({'x_from_date': from_date, 'x_to_date': to_date, 'x_reporter_id': env.company.x_reporter_id.id or env.ref('base.user_admin').id, 'x_excise_license_id': license})
        env['mail.activity'].create({'activity_type_id': env.ref('mail.mail_activity_data_todo').id, 'summary': f"Excise Report {res_id.x_name}",'res_model_id': env.ref('excise_management.excise_report').id, 'res_id': res_id.id, 'user_id': res_id.x_reporter_id.id, 'date_deadline': to_date + datetime.timedelta(weeks=1)})

mrp_installed = env['ir.module.module'].search([('name', '=', 'mrp'), ('state', '=', 'installed')])
for record in records:
    license = record.x_excise_license_id.id
    all_lines = env['stock.move.line'].search([
        ('date', '>=', record.x_from_date),
        ('date', '<=', record.x_to_date),
        '|', ('location_id.warehouse_id.x_excise_license_id', '=', license),
             ('location_dest_id.warehouse_id.x_excise_license_id', '=', license),
        ('x_excise_category', '!=', False), ('state', '=', 'done'),
    ])
    processed_lines_ids = {}
    for line in all_lines:
        src_is_fd = line.location_id.warehouse_id.x_is_fiscal_deposit and line.location_id.warehouse_id.x_excise_license_id.id == license
        dst_is_fd = line.location_dest_id.warehouse_id.x_is_fiscal_deposit and line.location_dest_id.warehouse_id.x_excise_license_id.id == license

        if src_is_fd and dst_is_fd: m_type = "transfer"
        elif mrp_installed and (line.production_id or line.move_id.production_id or line.workorder_id or line.move_id.workorder_id):
                                    m_type = "production"
        elif line.is_scrap or line.location_id.usage == 'inventory' or line.location_dest_id.usage == 'inventory':
                                    m_type = "scrap"
        elif src_is_fd:
            if line.location_dest_id.warehouse_id.x_is_fiscal_deposit or line.move_id.partner_id.property_account_position_id.x_is_fiscal_deposit:
                                    m_type = "exit fd"
            else:                   m_type = "exit"
        elif dst_is_fd:
            if line.location_id.warehouse_id.x_is_fiscal_deposit or line.move_id.partner_id.property_account_position_id.x_is_fiscal_deposit:
                                    m_type = "entry fd"
            else:                   m_type = "entry"
        else:
            # line does not change excise computation
            continue

        res = processed_lines_ids.setdefault(line.x_excise_category, {}).setdefault(m_type, {'qty': 0.0, 'amt': 0.0, 'pkg_unit': 0.0, 'pkg_amount': 0.0, 'lines': []})
        sign = dst_is_fd - src_is_fd
        res['qty'] += sign * line.x_excise_quantity
        res['amt'] += sign * line.x_excise_amount
        res['pkg_unit'] += sign * line.x_packaging_units
        res['pkg_amount'] += sign * line.x_packaging_amount
        res['lines'].append(line.id)

    record['x_line_ids'] = [(5, 0, 0)] + [
        (0, 0, {
            'x_excise_category_id': cat.id, 'x_excise_move_type': m_type, 
            'x_excise_quantity': data['qty'], 'x_excise_amount': data['amt'], 
            'x_excise_packaging_units': data['pkg_unit'], 'x_excise_packaging_amount': data['pkg_amount'], 
            'x_line_ids': [(6, 0, data['lines'])],
        }) for cat, types in processed_lines_ids.items() for m_type, data in types.items()
    ]
